import fs from "node:fs";
import path from "node:path";
const roots = process.argv.slice(2);
const files = [];
function walk(d){ for (const e of fs.readdirSync(d,{withFileTypes:true})) { const p=path.join(d,e.name); if (e.isDirectory()) { if (!/node_modules|\.git|docs/.test(p)) walk(p);} else if (p.endsWith(".mjs")||p.endsWith(".js")) files.push(p);} }
roots.forEach(walk);
const out = new Map();
for (const f of files) {
  const lines = fs.readFileSync(f,"utf8").split("\n");
  let ctx = "<module>";
  lines.forEach((l,i)=>{
    if (/^(export )?(async )?function\s+[A-Za-z0-9_$]+/.test(l)) ctx = l.match(/function\s+([A-Za-z0-9_$]+)/)[1];
    else if (/^(export )?(const|let)\s+[A-Za-z0-9_$]+\s*=\s*(async\s*)?\(/.test(l)) ctx = l.match(/^(?:export )?(?:const|let)\s+([A-Za-z0-9_$]+)/)[1];
    else if (/^(export )?(const|let)\s+[A-Za-z0-9_$]+\s*=\s*(async\s*)?function/.test(l)) ctx = l.match(/^(?:export )?(?:const|let)\s+([A-Za-z0-9_$]+)/)[1];
    else if (/^(test|it)\(/.test(l)) { const m=l.match(/^(?:test|it)\(\s*(["'`])(.*?)\1/); ctx = `test: ${m?m[2]:l.slice(0,60)}`; }
    else if (/^\t?(test|it)\(/.test(l) && /^(\t| {2,})/.test(l)) { const m=l.match(/(?:test|it)\(\s*(["'`])(.*?)\1/); if(m) ctx=`test: ${m[2]}`; }
    if (/\.query\(/.test(l) && !/\.query\(sql|db\.query\(|prepare\(/.test(l)) { const k=f; if(!out.has(k)) out.set(k,[]); out.get(k).push(`${i+1}: ${ctx}  :: ${l.trim().slice(0,90)}`); }
    if (/\bftsMatch\(/.test(l)) { if(!out.has(f)) out.set(f,[]); out.get(f).push(`${i+1}: ${ctx}  :: FTS ${l.trim().slice(0,80)}`); }
  });
}
for (const [f,arr] of out) { console.log(`\n## ${f}`); for (const a of arr) console.log("  "+a); }
EOF
